import {
  Mjml,
  MjmlBody,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  MjmlWrapper,
} from "@faire/mjml-react";
import { Fragment } from "react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

const colors = {
  border: "#e5e7eb",
  canvas: "#f1f5f9",
  dark: "#030712",
  muted: "#4b5563",
  subtle: "#6b7280",
  surface: "#fffffe",
  surfaceMuted: "#f9fafb",
} as const;

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

type BlogLayout =
  | "featured"
  | "featured-date"
  | "featured-date-full"
  | "horizontal-boxed"
  | "horizontal-split-images"
  | "masonry"
  | "masonry-boxed"
  | "podcast-full"
  | "podcast-split"
  | "single-horizontal"
  | "two-column-boxed"
  | "two-column-images"
  | "two-column-images-text";

interface BlogPostData {
  author?: string;
  badge?: string;
  date?: string;
  episode?: string;
  excerpt: string;
  host?: string;
  imageAlt: string;
  imageSrc: string;
  imageAlt2?: string;
  imageSrc2?: string;
  month?: string;
  title: string;
}

const Image = ({
  alt,
  src,
  width,
}: {
  alt: string;
  src: string;
  width: number;
}) => (
  <MjmlImage
    alt={alt}
    borderRadius="8px"
    padding="0"
    src={src}
    width={`${width}px`}
  />
);

const Meta = ({
  boxed = false,
  post,
}: {
  boxed?: boolean;
  post: BlogPostData;
}) => {
  const label =
    post.episode ??
    post.badge ??
    (post.date && post.month ? `${post.date} ${post.month}` : undefined);
  return (() => {
    if (label) {
      return (
        <MjmlText
          color={colors.subtle}
          fontFamily={fontFamily}
          fontSize="12px"
          fontWeight="600"
          letterSpacing="0.04em"
          lineHeight="16px"
          padding={boxed ? "20px 20px 0" : "0"}
          textTransform="uppercase"
        >
          {label}
        </MjmlText>
      );
    }
    return null;
  })();
};

const Copy = ({
  boxed = false,
  post,
}: {
  boxed?: boolean;
  post: BlogPostData;
}) => {
  const hasMeta = Boolean(
    post.episode ?? post.badge ?? (post.date && post.month)
  );
  const horizontalPadding = boxed ? "20px" : "0";
  let titleTopPadding = 0;
  if (hasMeta) {
    titleTopPadding = 8;
  } else if (boxed) {
    titleTopPadding = 20;
  }
  let footer: ReactNode = null;
  if (post.author || post.host) {
    footer = (
      <MjmlText
        color={colors.subtle}
        fontFamily={fontFamily}
        fontSize="12px"
        lineHeight="16px"
        padding={`12px ${horizontalPadding} ${boxed ? "20px" : "0"}`}
      >
        {post.host ? `Hosted by ${post.host}` : `By ${post.author}`}
      </MjmlText>
    );
  } else if (boxed) {
    footer = <MjmlSpacer height="20px" />;
  }
  return (
    <>
      <Meta boxed={boxed} post={post} />
      <MjmlText
        color={colors.dark}
        fontFamily={fontFamily}
        fontSize="20px"
        fontWeight="600"
        lineHeight="28px"
        padding={`${titleTopPadding}px ${horizontalPadding} 0`}
      >
        {post.title}
      </MjmlText>
      <MjmlText
        color={colors.muted}
        fontFamily={fontFamily}
        fontSize="14px"
        lineHeight="22px"
        padding={`10px ${horizontalPadding} 0`}
      >
        {post.excerpt}
      </MjmlText>
      {footer}
    </>
  );
};

const VerticalCard = ({
  boxed = false,
  post,
  width = 264,
}: {
  boxed?: boolean;
  post: BlogPostData;
  width?: number;
}) => (
  <>
    <Image alt={post.imageAlt} src={post.imageSrc} width={width} />
    {boxed ? null : <MjmlSpacer height="16px" />}
    <Copy boxed={boxed} post={post} />
  </>
);

const TwoColumns = ({
  boxed,
  posts,
}: {
  boxed: boolean;
  posts: readonly BlogPostData[];
}) => (
  <MjmlSection padding="0">
    {posts.slice(0, 2).map((post, index) => (
      <MjmlColumn
        backgroundColor={boxed ? colors.surfaceMuted : undefined}
        border={boxed ? `1px solid ${colors.border}` : undefined}
        borderRadius="8px"
        key={`${post.title}-${index}`}
        padding={index === 0 ? "0 12px 0 0" : "0 0 0 12px"}
        verticalAlign="top"
        width="50%"
      >
        <VerticalCard boxed={boxed} post={post} />
      </MjmlColumn>
    ))}
  </MjmlSection>
);

const Masonry = ({
  boxed,
  posts,
}: {
  boxed: boolean;
  posts: readonly BlogPostData[];
}) => (
  <MjmlSection padding="0">
    <MjmlColumn
      backgroundColor={boxed ? colors.surfaceMuted : undefined}
      border={boxed ? `1px solid ${colors.border}` : undefined}
      borderRadius="8px"
      padding="0 12px 0 0"
      verticalAlign="top"
      width="50%"
    >
      <VerticalCard boxed={boxed} post={posts[0]} />
    </MjmlColumn>
    <MjmlColumn padding="0 0 0 12px" verticalAlign="top" width="50%">
      {posts.slice(1, 3).map((post, index) => (
        <Fragment key={`${post.title}-${index}`}>
          <VerticalCard boxed={boxed} post={post} />
          {index === 0 ? <MjmlSpacer height="16px" /> : null}
        </Fragment>
      ))}
    </MjmlColumn>
  </MjmlSection>
);

const Horizontal = ({
  boxed = false,
  post,
}: {
  boxed?: boolean;
  post: BlogPostData;
}) => (
  <MjmlSection
    backgroundColor={boxed ? colors.surfaceMuted : undefined}
    border={boxed ? `1px solid ${colors.border}` : undefined}
    borderRadius="8px"
    padding="0"
  >
    <MjmlColumn padding="0" verticalAlign="middle" width="220px">
      <Image alt={post.imageAlt} src={post.imageSrc} width={220} />
    </MjmlColumn>
    <MjmlColumn padding={boxed ? "0" : "0 0 0 24px"} verticalAlign="middle">
      <Copy boxed={boxed} post={post} />
    </MjmlColumn>
  </MjmlSection>
);

const SplitImages = ({ post }: { post: BlogPostData }) => (
  <MjmlSection
    backgroundColor={colors.surfaceMuted}
    border={`1px solid ${colors.border}`}
    borderRadius="8px"
    padding="0"
  >
    <MjmlColumn padding="0 4px 0 0" verticalAlign="middle" width="112px">
      <Image alt={post.imageAlt} src={post.imageSrc} width={112} />
    </MjmlColumn>
    <MjmlColumn padding="0 0 0 4px" verticalAlign="middle" width="112px">
      <Image
        alt={post.imageAlt2 ?? ""}
        src={post.imageSrc2 ?? post.imageSrc}
        width={112}
      />
    </MjmlColumn>
    <MjmlColumn padding="0" verticalAlign="middle">
      <Copy boxed post={post} />
    </MjmlColumn>
  </MjmlSection>
);

const FullWidth = ({ post }: { post: BlogPostData }) => (
  <MjmlSection padding="0">
    <MjmlColumn padding="0">
      <Image alt={post.imageAlt} src={post.imageSrc} width={552} />
      <MjmlSpacer height="20px" />
      <Copy post={post} />
    </MjmlColumn>
  </MjmlSection>
);

const BlogContent = ({
  layout,
  posts,
}: {
  layout: BlogLayout;
  posts: readonly BlogPostData[];
}) => {
  if (layout === "horizontal-split-images") {
    return <SplitImages post={posts[0]} />;
  }
  if (
    layout === "horizontal-boxed" ||
    layout === "podcast-split" ||
    layout === "featured-date"
  ) {
    return <Horizontal boxed={layout === "horizontal-boxed"} post={posts[0]} />;
  }
  if (layout === "single-horizontal") {
    return <Horizontal post={posts[0]} />;
  }
  if (layout === "masonry" || layout === "masonry-boxed") {
    return <Masonry boxed={layout === "masonry-boxed"} posts={posts} />;
  }
  if (
    layout === "two-column-images" ||
    layout === "two-column-images-text" ||
    layout === "two-column-boxed"
  ) {
    return <TwoColumns boxed={layout === "two-column-boxed"} posts={posts} />;
  }
  return <FullWidth post={posts[0]} />;
};

const BlogEmailShell = ({
  children,
  preview,
  theme,
}: {
  children: ReactNode;
  preview: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody backgroundColor={colors.canvas} width={theme.containerWidth}>
      <MjmlWrapper backgroundColor={colors.surface} padding="44px 24px">
        {children}
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

interface PodcastSplit_PodcastBlogSplitProps {
  theme?: EmailTheme;
  episode?: string;
  excerpt?: string;
  host?: string;
  imageAlt?: string;
  imageSrc?: string;
  title?: string;
}

const PodcastSplit_PodcastBlogSplitSection = ({
  episode = "Episode 42",
  excerpt = "A conversation about emerging email trends and technologies.",
  host = "Jane Smith",
  imageAlt = "Podcast studio",
  imageSrc = emailAsset("hero/mosaic-1.jpg"),
  title = "The future of email",
}: Omit<PodcastSplit_PodcastBlogSplitProps, "theme">) => {
  const posts = [
    {
      episode,
      excerpt,
      host,
      imageAlt,
      imageSrc,
      title,
    },
  ];
  return (
    <>
      <BlogContent layout="podcast-split" posts={posts} />
    </>
  );
};

const PodcastSplit_PodcastBlogSplit = ({
  theme = defaultTheme,
  episode = "Episode 42",
  excerpt = "A conversation about emerging email trends and technologies.",
  host = "Jane Smith",
  imageAlt = "Podcast studio",
  imageSrc = emailAsset("hero/mosaic-1.jpg"),
  title = "The future of email",
}: PodcastSplit_PodcastBlogSplitProps) => (
  <BlogEmailShell preview={title} theme={theme}>
    <PodcastSplit_PodcastBlogSplitSection
      episode={episode}
      excerpt={excerpt}
      host={host}
      imageAlt={imageAlt}
      imageSrc={imageSrc}
      title={title}
    />
  </BlogEmailShell>
);

PodcastSplit_PodcastBlogSplit.PreviewProps = {
  episode: "Episode 42",
  excerpt: "A conversation about emerging email trends and technologies.",
  host: "Jane Smith",
  imageAlt: "Podcast studio",
  imageSrc: emailAsset("hero/mosaic-1.jpg"),
  theme: defaultTheme,
  title: "The future of email",
} satisfies PodcastSplit_PodcastBlogSplitProps;

const __PodcastSplit = PodcastSplit_PodcastBlogSplit;

interface PodcastFull_PodcastFullWidthProps {
  theme?: EmailTheme;
  episode?: string;
  excerpt?: string;
  imageAlt?: string;
  imageSrc?: string;
  title?: string;
}

const PodcastFull_PodcastFullWidthSection = ({
  episode = "Episode 42",
  excerpt = "A conversation about emerging email trends and technologies.",
  imageAlt = "Podcast studio",
  imageSrc = emailAsset("image-grids/full-width-3.jpg"),
  title = "The future of email",
}: Omit<PodcastFull_PodcastFullWidthProps, "theme">) => {
  const posts = [
    {
      episode,
      excerpt,
      imageAlt,
      imageSrc,
      title,
    },
  ];
  return (
    <>
      <BlogContent layout="podcast-full" posts={posts} />
    </>
  );
};

const PodcastFull_PodcastFullWidth = ({
  theme = defaultTheme,
  episode = "Episode 42",
  excerpt = "A conversation about emerging email trends and technologies.",
  imageAlt = "Podcast studio",
  imageSrc = emailAsset("image-grids/full-width-3.jpg"),
  title = "The future of email",
}: PodcastFull_PodcastFullWidthProps) => (
  <BlogEmailShell preview={title} theme={theme}>
    <PodcastFull_PodcastFullWidthSection
      episode={episode}
      excerpt={excerpt}
      imageAlt={imageAlt}
      imageSrc={imageSrc}
      title={title}
    />
  </BlogEmailShell>
);

PodcastFull_PodcastFullWidth.PreviewProps = {
  episode: "Episode 42",
  excerpt: "A conversation about emerging email trends and technologies.",
  imageAlt: "Podcast studio",
  imageSrc: emailAsset("image-grids/full-width-3.jpg"),
  theme: defaultTheme,
  title: "The future of email",
} satisfies PodcastFull_PodcastFullWidthProps;

const __PodcastFull = PodcastFull_PodcastFullWidth;

export interface BlogPost {
  title: string;
  excerpt?: string;
  image?: {
    alt?: string;
    src: string;
  };
  author?: string;
  badge?: string;
  date?: string;
  month?: string;
  episode?: string;
  host?: string;
}

export interface PodcastBlogProps {
  theme?: Parameters<typeof __PodcastSplit>[0]["theme"];
  post?: BlogPost;
  width?: "split" | "full";
}

const toPodcastProps = (post: BlogPost | undefined) =>
  post
    ? {
        episode: post.episode,
        excerpt: post.excerpt,
        host: post.host,
        imageAlt: post.image?.alt,
        imageSrc: post.image?.src,
        title: post.title,
      }
    : {};

export const PodcastBlog = ({
  theme,
  post,
  width = "split",
}: PodcastBlogProps) => {
  const props = { theme, ...toPodcastProps(post) };
  return width === "full" ? (
    <__PodcastFull {...props} />
  ) : (
    <__PodcastSplit {...props} />
  );
};

PodcastBlog.PreviewProps = {
  width: "split",
} satisfies PodcastBlogProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
